import hmac
import hashlib
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    # Parse JSON body (body may have whitespace that affects v1 signature)
    try:
        body_bytes = raw_body
        data = json.loads(body_bytes.decode("utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification("Invalid JSON body")

    # Check required fields
    string_fields = {"event_id", "account_id", "currency"}
    for field in ("event_id", "account_id", "amount_minor", "currency"):
        if field not in data:
            raise InvalidNotification(f"Missing required field: {field}")
        if field in string_fields:
            if not isinstance(data[field], str) or not data[field]:
                raise InvalidNotification(f"Field {field} must be nonempty string")
        elif field == "amount_minor":
            if not isinstance(data[field], int):
                raise InvalidNotification(f"Field {field} must be integer, got {type(data[field]).__name__}")
        elif field == "currency":
            if isinstance(data[field], str) and (len(data[field]) != 3 or not data[field].isupper()):
                raise InvalidNotification(f"Field {field} must be three uppercase ASCII letters")

    # Verify timestamp is within acceptance window
    timestamp_str = headers.get("X-Pay-Timestamp", "")
    try:
        timestamp = int(timestamp_str)
    except (ValueError, TypeError):
        raise InvalidNotification("Malformed timestamp")

    diff = abs(now - timestamp)
    if diff > 300:
        raise InvalidNotification("Timestamp outside acceptance window (max 300s)")

    # Validate v1 signature if present
    v1_sig = headers.get("X-Pay-Signature", "")
    v1_valid = False
    if v1_sig and v1_sig.startswith("v1="):
        # v1: HMAC-SHA256(ascii_timestamp + "." + raw_body_bytes)
        compute = hmac.new(
            secret, timestamp_str.encode("ascii") + b"." + body_bytes, hashlib.sha256
        ).hexdigest()
        if v1_sig[3:] == compute:
            v1_valid = True

    # If v1 is valid, use it; otherwise check r0 fallback
    if v1_valid:
        return {
            "event_id": data["event_id"],
            "account_id": data["account_id"],
            "amount_minor": data["amount_minor"],
            "currency": data["currency"],
        }

    # v1 signature is absent or invalid; try r0 path
    r0_receipt = headers.get("X-Pay-Receipt", "")
    if not r0_receipt or not r0_receipt.startswith("r0="):
        raise InvalidNotification("No valid receipt or v1 signature presence")

    r0_digest = r0_receipt[3:]  # strip "r0=" prefix
    # r0: HMAC-SHA256(ascii_timestamp + "." + UTF-8 event_id_bytes)
    compute = hmac.new(
        secret, timestamp_str.encode("ascii") + b"." + data["event_id"].encode("utf-8"), hashlib.sha256
    ).hexdigest()
    if r0_digest == compute:
        # r0 path succeeded, return parsed values (exact same format as v1)
        return {
            "event_id": data["event_id"],
            "account_id": data["account_id"],
            "amount_minor": data["amount_minor"],
            "currency": data["currency"],
        }
    else:
        raise InvalidNotification("r0 receipt digest mismatch")
